def dedupe_preserving_order(items: list[str]) -> list[str]:
    out: list[str] = []
    for item in items:
        duplicate = False
        for existing in out:
            if existing == item:
                duplicate = True
        if not duplicate:
            out.append(item)
    return out

function dedupePreservingOrder(items: string[]): string[] {
    const out: string[] = [];
    for (const item of items) {
        let duplicate = false;
        for (const existing of out) {
            if (existing === item) {
                duplicate = true;
            }
        }
        if (!duplicate) {
            out.push(item);
        }
    }
    return out;
}

func DedupePreservingOrder(items []string) []string {
    out := []string{}
    for _, item := range items {
        duplicate := false
        for _, existing := range out {
            if existing == item {
                duplicate = true
            }
        }
        if !duplicate {
            out = append(out, item)
        }
    }
    return out
}

fn dedupe_preserving_order(items: &[&str]) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for item in items {
        let mut duplicate = false;
        for existing in &out {
            if existing == item {
                duplicate = true;
            }
        }
        if !duplicate {
            out.push(item.to_string());
        }
    }
    out
}
